/* global React, ReactDOM */
const { useState, useEffect, useRef } = React;

// ─── Scroll position hook ───────────────────────────────────
function useScrollY() {
  const [y, setY] = useState(0);
  useEffect(() => {
    const h = () => setY(window.scrollY);
    window.addEventListener("scroll", h, { passive: true });
    return () => window.removeEventListener("scroll", h);
  }, []);
  return y;
}

// ─── IntersectionObserver hook ──────────────────────────────
function useInView(ref, threshold = 0.2) {
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) setVisible(true); },
      { threshold }
    );
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [ref, threshold]);
  return visible;
}

// ════════════════════════════════════════════════════════════
// PRELOADER
// ════════════════════════════════════════════════════════════
function Preloader({ onDone }) {
  const [phase, setPhase]   = useState("fill");
  const [fillH, setFillH]   = useState(0);

  useEffect(() => {
    let start = null;
    const duration = 1600;
    function step(ts) {
      if (!start) start = ts;
      const p    = Math.min((ts - start) / duration, 1);
      const ease = p < 0.5 ? 2 * p * p : -1 + (4 - 2 * p) * p;
      setFillH(ease * 100);
      if (p < 1) requestAnimationFrame(step);
      else setTimeout(() => setPhase("exit"), 400);
    }
    requestAnimationFrame(step);
  }, []);

  useEffect(() => {
    if (phase === "exit") setTimeout(onDone, 800);
  }, [phase, onDone]);

  return (
    <div className={`preloader${phase === "exit" ? " exit" : ""}`}>
      <div className="preloader-inner">
        <span className="preloader-shadow">Anamika.</span>
        <span
          className={`preloader-fill${phase === "exit" ? " fading" : ""}`}
          style={{ clipPath: `inset(${100 - fillH}% 0 0 0)` }}
        >
          Anamika.
        </span>
      </div>
    </div>
  );
}

