// NAVBAR
// ════════════════════════════════════════════════════════════
function Navbar() {
  const scrollY  = useScrollY();
  const [open, setOpen] = useState(false);
  const scrolled = scrollY > 60;
  const links    = ["Home", "About", "Skills", "Projects", "Experience", "Education", "Certifications", "Contact"];

  return (
    <>
      <nav className={`navbar${scrolled ? " scrolled" : ""}`}>
        {/* Logo */}
        <span className="nav-logo">Anamika<span>.</span></span>

        {/* Desktop links */}
        <div className="nav-links">
          {links.map(l => (
            <a key={l} href={`#${l.toLowerCase()}`}>{l}</a>
          ))}
        </div>

        {/* Hire Me */}
        <a href="#contact" className="hire-btn">Hire Me</a>

        {/* Hamburger */}
        <button
          className={`hamburger${open ? " open" : ""}`}
          onClick={() => setOpen(!open)}
          aria-label="Toggle menu"
        >
          <span></span><span></span><span></span>
        </button>
      </nav>

      {/* Mobile menu */}
      <div className={`mobile-menu${open ? " open" : ""}`}>
        {links.map(l => (
          <a key={l} href={`#${l.toLowerCase()}`} onClick={() => setOpen(false)}>{l}</a>
        ))}
      </div>
    </>
  );
}

